const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],clamp=T.MathUtils.clamp;
const ui={mode:'garage',filter:'all',selected:'hood',color:'#d88627',night:false,wet:false,warm:true,sound:true,headlights:false,wipers:false,chase:false,lookYaw:0,lookPitch:-.09,reachTime:0,interaction:0,garageState:null};
