const reachTarget=new T.Vector3(),ray=new T.Raycaster(),mouse=new T.Vector2();
const touchPoints=[{name:'Зажигание',pos:new T.Vector3(-.24,.735,-.39),action:()=>toggleIgnition()},{name:'Свет',pos:new T.Vector3(-.53,.73,-.4),action:()=>toggleHeadlights()},{name:'Центральная консоль',pos:new T.Vector3(.04,.67,-.31),action:()=>{audio.horn();toast('Касание центральной консоли')}},{name:'Руль',pos:new T.Vector3(-.3174,.76,-.4002),action:()=>{audio.horn();toast('Кнопка звукового сигнала')}}];
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function renderParts(){if(!car)return;const select=$('#partSelect');select.textContent='';for(const [category,label] of [['body','Кузов и механизмы'],['interior','Салон'],['wheels','Колёса и подвеска']]){const group=document.createElement('optgroup');group.label=label;for(const part of car.parts.filter(p=>p.category===category)){const option=document.createElement('option');option.value=part.id;option.textContent=part.name;group.append(option)}select.append(group)}select.disabled=false;syncPartUI()}
function syncPartUI(){if(!car)return;const p=car.parts.find(p=>p.id===ui.selected);if(!p)return;$('#partSelect').value=p.id;$$('[data-quick]').forEach(b=>b.classList.toggle('active',b.dataset.quick===p.id));$('#partStatus').textContent=p.detached?'Снята':p.openable?(p.targetOpen>.9?'Открыта':p.targetOpen>.05?'Приоткрыта':'Закрыта'):'На месте';$('#selectedTitle').textContent=p.name;$('#selectedDescription').textContent=p.description;$('#openAmount').disabled=!p.openable||p.detached;$('#openAmount').value=p.targetOpen*100;$('#openValue').textContent=Math.round(p.targetOpen*100)+'%';$('#openingDetails').hidden=!p.openable||p.detached;$('#togglePart').hidden=!p.openable||p.detached;$('#togglePart').disabled=false;$('#togglePart').innerHTML=(p.targetOpen>.5?'Закрыть':'Открыть')+' <span>↗</span>';$('#detachPart').disabled=false;$('#detachPart').textContent=p.detached?'Вернуть на место':'Снять деталь';$('#detachPart').classList.toggle('sole-action',p.detached||!p.openable);$('#focusPart').disabled=false;$('#partHint').textContent=p.detached?'Деталь снята. Нажмите «Вернуть на место», чтобы установить её обратно.':p.openable?'Откройте деталь или снимите её целиком. В любой момент можно вернуть всё на место.':'Эту деталь можно снять и установить обратно.';}
function selectPart(id){if(!car||!car.parts.some(p=>p.id===id))return;ui.selected=id;syncPartUI()}
$('#partSelect').onchange=e=>selectPart(e.target.value);$$('[data-quick]').forEach(b=>b.onclick=()=>selectPart(b.dataset.quick));
$('#openAmount').oninput=e=>{if(car){car.setOpen(ui.selected,+e.target.value/100);syncPartUI()}};$('#togglePart').onclick=()=>{if(car){const p=car.parts.find(p=>p.id===ui.selected);car.setOpen(p.id,p.targetOpen>.5?0:1);syncPartUI()}};$('#detachPart').onclick=()=>{if(car){const p=car.parts.find(p=>p.id===ui.selected);car.setDetached(p.id,!p.detached);syncPartUI();toast(p.detached?'Деталь снята. Можно вернуть её на место.':'Деталь вернулась на место')}};$('#explode').oninput=e=>{if(car)car.setExplode(+e.target.value/100);$('#explodeValue').textContent=e.target.value+'%'};$('#openAll').onclick=()=>{if(car){car.parts.filter(p=>p.openable).forEach(p=>car.setOpen(p.id,1));syncPartUI()}};$('#assemble').onclick=()=>{if(car){car.reset();$('#explode').value=0;$('#explodeValue').textContent='0%';syncPartUI();toast('Автомобиль собран')}};
function focusPart(){if(!car)return;const p=car.parts.find(p=>p.id===ui.selected),target=car.focusPoint(p.id),size=new T.Box3().setFromObject(p.node).getSize(new T.Vector3()).length(),dir=camera.position.clone().sub(orbit.target).normalize();orbit.target.copy(target);camera.position.copy(target).addScaledVector(dir,clamp(size*1.3,1.2,6));orbit.update()}$('#focusPart').onclick=focusPart;
function fitGarage(view='front'){if(!camera||!orbit)return;orbit.enabled=true;camera.fov=38;camera.updateProjectionMatrix();if(view==='interior'){orbit.target.set(-.32,.8,-.6);camera.position.set(-.32,1.03,.25);orbit.minDistance=.06;orbit.maxDistance=20;}else{orbit.minDistance=1.1;orbit.maxDistance=18;orbit.target.set(0,.57,0);const distance=Math.max(6.6,4.9/(2*Math.tan(T.MathUtils.degToRad(camera.fov/2))*camera.aspect));camera.position.set(view==='rear'?-distance*.78:-distance*.76,distance*.40,view==='rear'?distance*.85:-distance*.91)}orbit.update();}
$$('[data-view]').forEach(b=>b.onclick=()=>fitGarage(b.dataset.view));$('#resetView').onclick=()=>fitGarage();$('#snapshot').onclick=()=>{if(!renderer||!ready)return;renderer.render(scene,camera);const c=document.createElement('canvas'),source=renderer.domElement;c.width=source.width;c.height=source.height;const ctx=c.getContext('2d'),g=ctx.createRadialGradient(c.width*.5,c.height*.4,0,c.width*.5,c.height*.5,c.height);g.addColorStop(0,'#454b45');g.addColorStop(1,'#18262c');ctx.fillStyle=g;ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(source,0,0);ctx.fillStyle='#e8bd91';ctx.font=`${Math.max(15,c.width/45)}px Arial`;ctx.fillText('TORQUE / MOTOR LAB',c.width*.04,c.height*.95);c.toBlob(b=>{if(b)download(b,'torque-garage.png')},'image/png')};$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#workbench').requestFullscreen()}catch{toast('Полноэкранный режим недоступен')}};
$$('[data-color]').forEach(b=>b.onclick=()=>{ui.color=b.dataset.color;car?.setColor(ui.color);$$('[data-color]').forEach(x=>x.classList.toggle('active',x===b))});$('#lighting').onclick=()=>{ui.warm=!ui.warm;$('#lighting').textContent=ui.warm?'Тёплый':'Холодный';if(sun)sun.color.set(ui.warm?'#ffe1c1':'#d2e4ff')};$('#weather').onclick=()=>{ui.wet=!ui.wet;$('#weather').textContent=ui.wet?'Дождь':'Сухо';simulation.setSurface(ui.wet?'wet':'dry');world?.setWeather(ui.wet?'rain':'clear');if(ui.mode==='drive')applyEnvironment()};$('#timeOfDay').onclick=()=>{ui.night=!ui.night;$('#timeOfDay').textContent=ui.night?'Вечер':'День';if(ui.mode==='drive')applyEnvironment()};$('#sound').onclick=()=>{ui.sound=!ui.sound;audio.setEnabled(ui.sound);$('#sound').textContent=ui.sound?'Включён':'Выключен';if(ui.sound)audio.unlock()};
const about=$('#aboutDialog');$('#aboutButton').onclick=$('#aboutFooter').onclick=()=>about.showModal();$('#closeAbout').onclick=()=>about.close();about.onclick=e=>{if(e.target!==about)return;const r=about.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)about.close()};$('#saveState').onclick=()=>{if(car)download(new Blob([JSON.stringify({app:'TORQUE',version:1,assembly:car.getState(),drive:simulation.getState(),note:'Учебная визуализация, не ремонтная или инженерная документация.'},null,2)],{type:'application/json'}),'torque-assembly.json')};
function restoreGarage(){if(!car)return;car.reset();car.group.position.set(0,0,0);car.group.rotation.set(0,0,0);if(ui.garageState){for(const p of ui.garageState.parts){car.setOpen(p.id,p.open);car.setDetached(p.id,p.detached)}car.setExplode(ui.garageState.explode);car.setColor(ui.garageState.color);}car.update(.1);syncPartUI()}
function mode(value){if(!ready)return toast('Дождитесь загрузки автомобиля');if(value===ui.mode)return;if(value==='drive'){ui.garageState=car.getState();car.reset();simulation.reset();simulation.setGear('N');simulation.setSurface(ui.wet?'wet':'dry');simulation.setRoadFunction(z=>({centerX:roadCenter(z),halfWidth:4.2}));ui.lookYaw=0;ui.lookPitch=-.09;ui.chase=false;ui.reachTime=0;keys.clear();for(const k in touch)touch[k]=false;audio.setEnabled(ui.sound);orbit.enabled=false;camera.fov=75;camera.near=.025;camera.far=2000;camera.updateProjectionMatrix();hands?.setEnabled(true);world.setEnabled(true);garage.visible=false;toast('Нажмите «Завести и ехать», затем удерживайте газ.')}else{keys.clear();simulation.setInput({throttle:0,brake:1,steer:0});simulation.setIgnition(false);audio.setEnabled(false);audio.update(0,{...simulation.getState(),speedKmh:0,lateralAcceleration:0,brake:0});hands?.setEnabled(false);world.setEnabled(false);garage.visible=true;restoreGarage();camera.near=.04;camera.far=500;fitGarage();}ui.mode=value;document.body.classList.toggle('drive-mode',value==='drive');$('#driveOverlay').hidden=value!=='drive';$$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===value);b.setAttribute('aria-pressed',b.dataset.mode===value)});$('#driveCamera').textContent='Вид: из салона';$('#sceneLabel').textContent=value==='drive'?'Поездка':'McLaren P1';applyEnvironment();syncDriveUI(simulation.getState());resize();}
$$('[data-mode]').forEach(b=>b.onclick=()=>mode(b.dataset.mode));$('#enterDrive').onclick=()=>mode('drive');$('#exitDrive').onclick=()=>mode('garage');
function toggleIgnition(){audio.unlock();const s=simulation.getState();if(s.speedKmh>3&&s.engineOn){toast('Остановитесь перед выключением двигателя');return}simulation.setIgnition(!s.engineOn);reachTo(touchPoints[0].pos);syncDriveUI(simulation.getState());toast(s.engineOn?'Двигатель выключен':'Двигатель запущен. Нажмите «Поехать вперёд».')}
function reachTo(pos){if(!handMount||!car)return;car.group.updateMatrixWorld(true);reachTarget.copy(handMount.worldToLocal(car.group.localToWorld(pos.clone())));ui.reachTime=1.25;}
function toggleHeadlights(){ui.headlights=!ui.headlights;car?.setLights(ui.headlights);if(headlampGroup)headlampGroup.visible=ui.headlights;$('#headlights').classList.toggle('active',ui.headlights);$('#headlights span').textContent=ui.headlights?'Выключить фары':'Включить фары';$('#lightStatus').textContent=ui.headlights?'БЛИЖНИЙ СВЕТ':'СВЕТ ВЫКЛ.';reachTo(touchPoints[1].pos)}
function startDriving(){if(ui.mode!=='drive')return;audio.unlock();simulation.setIgnition(true);if(!simulation.setGear('D'))return toast('Сначала остановитесь.');reachTo(touchPoints[0].pos);$('.drive-extra').open=false;syncDriveUI(simulation.getState());toast(innerWidth<=600?'Удерживайте «Газ», чтобы ехать.':'Удерживайте W или ↑ для газа. A и D поворачивают руль.')}
$('#startDriving').onclick=startDriving;$('#ignition').onclick=toggleIgnition;$('#headlights').onclick=toggleHeadlights;$('#horn').onclick=()=>{audio.unlock();audio.horn();reachTo(touchPoints[3].pos)};$('#wipers').onclick=()=>{ui.wipers=!ui.wipers;$('#wipers').classList.toggle('active',ui.wipers);$('#wipers span').textContent=ui.wipers?'Выключить дворник':'Включить дворник';reachTo(touchPoints[1].pos)};
function resetDriving(){const engine=simulation.getState().engineOn;simulation.reset();simulation.setGear('N');simulation.setIgnition(engine);simulation.setSurface(ui.wet?'wet':'dry');ui.lookYaw=0;ui.lookPitch=-.09;keys.clear();toast('Автомобиль возвращён на начало маршрута')};$('#resetDrive').onclick=resetDriving;$('#driveCamera').onclick=()=>{ui.chase=!ui.chase;hands?.setEnabled(!ui.chase);$('#driveCamera').textContent=ui.chase?'Вид: снаружи':'Вид: из салона';camera.fov=ui.chase?58:75;camera.updateProjectionMatrix()};
$$('[data-gear]').forEach(b=>b.onclick=()=>{if(!simulation.setGear(b.dataset.gear))return toast('Остановитесь перед сменой направления');audio.unlock();reachTo(touchPoints[2].pos);syncDriveUI(simulation.getState())});
function interact(){if(ui.mode!=='drive')return;const point=touchPoints[ui.interaction]||touchPoints[0];point.action();reachTo(point.pos);}
const keyMap={KeyW:'throttle',ArrowUp:'throttle',KeyS:'brake',ArrowDown:'brake',KeyA:'left',ArrowLeft:'left',KeyD:'right',ArrowRight:'right'};
document.addEventListener('keydown',e=>{if(about.open||ui.mode!=='drive'||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if(['Enter','Space'].includes(e.code)&&['BUTTON','A','SUMMARY'].includes(document.activeElement.tagName))return;if(keyMap[e.code]||e.code==='Space')e.preventDefault();keys.add(e.code);if(e.repeat)return;const actions={Enter:toggleIgnition,KeyL:toggleHeadlights,KeyH:()=>$('#horn').click(),KeyX:()=>$('#wipers').click(),KeyC:()=>$('#driveCamera').click(),KeyR:resetDriving,KeyE:interact};actions[e.code]?.();});document.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();for(const k in touch)touch[k]=false;simulation.setInput({throttle:0,brake:1,steer:0,handbrake:0})});$$('[data-touch]').forEach(b=>{const set=value=>{touch[b.dataset.touch]=value;b.classList.toggle('pressed',value)};b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);set(true);audio.unlock()};b.onpointerup=b.onpointercancel=b.onlostpointercapture=()=>set(false)});
$$('#driveOverlay button').forEach(b=>b.addEventListener('click',()=>b.blur()));
function input(){const active={...touch};for(const k of keys){if(keyMap[k])active[keyMap[k]]=true}return {throttle:active.throttle?1:0,brake:active.brake?1:0,steer:(active.left?1:0)-(active.right?1:0),handbrake:keys.has('Space')?1:0};}
function syncDriveUI(s){$('#speedValue').textContent=Math.round(s.speedKmh);$('#rpmValue').textContent=Math.round(s.rpm/100)*100;$('#rpmBar').style.width=clamp(s.rpm/7100*100,0,100)+'%';$('#gearLarge').textContent=s.selectedGear;$('#tripDistance').textContent=(s.distance/1000).toFixed(2)+' км';$('#engineStatus').textContent=s.engineOn?'Двигатель работает':'Двигатель выключен';$('#ignition').classList.toggle('active',s.engineOn);$('#ignition span').textContent=s.engineOn?'Заглушить двигатель':'Завести двигатель';$('#throttleBar').style.width=s.throttle*100+'%';$('#brakeBar').style.width=s.brake*100+'%';$('#roadLabel').textContent=s.offroad?'Обочина — сцепление ниже':ui.wet?'Мокрая дорога':'Загородная дорога';$$('[data-gear]').forEach(b=>{b.classList.toggle('active',b.dataset.gear===s.selectedGear);b.setAttribute('aria-pressed',b.dataset.gear===s.selectedGear)});$('#driveWelcome').hidden=s.engineOn&&(s.selectedGear!=='N'||s.speedKmh>1);$('#welcomeTitle').textContent=s.engineOn?'Можно ехать':'Готовы к поездке?';$('#welcomeText').textContent=s.engineOn?'Двигатель работает. Нажмите кнопку, чтобы включить движение вперёд.':'Одна кнопка заведёт двигатель и включит передачу вперёд.';$('#startDriving').innerHTML=(s.engineOn?'Поехать вперёд':'Завести и ехать')+' <span>→</span>';}

function minimap(s){const canvas=$('#miniMap'),ctx=canvas.getContext('2d');if(!ctx)return;const w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.save();ctx.beginPath();ctx.arc(w/2,h/2,w*.48,0,Math.PI*2);ctx.clip();ctx.fillStyle='#14201bf0';ctx.fillRect(0,0,w,h);const scale=.30;ctx.translate(w/2,h*.65);ctx.rotate(s.yaw);ctx.translate(-s.position.x*scale,-s.position.z*scale);ctx.lineCap='round';ctx.beginPath();for(let z=s.position.z-450;z<=s.position.z+250;z+=8){const x=roadCenter(z)*scale,y=z*scale;if(z===s.position.z-450)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.strokeStyle='#839482';ctx.lineWidth=6;ctx.stroke();ctx.strokeStyle='#d7c394';ctx.lineWidth=1;ctx.stroke();ctx.restore();ctx.fillStyle='#e4b07c';ctx.beginPath();ctx.moveTo(w/2,h*.65-7);ctx.lineTo(w/2-5,h*.65+5);ctx.lineTo(w/2+5,h*.65+5);ctx.closePath();ctx.fill();ctx.fillStyle='#91aa8c';ctx.font='9px Arial';ctx.textAlign='center';ctx.fillText('N',w/2,17);}
function resize(){if(!renderer||!camera)return;const r=$('#canvas').getBoundingClientRect();if(!r.width||!r.height)return;renderer.setSize(r.width,r.height);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();}
let sky,skyMaterial,ambientCockpit;
function makeSky(){skyMaterial=new T.ShaderMaterial({side:T.BackSide,depthWrite:false,uniforms:{uNight:{value:0}},vertexShader:'varying vec3 vDirection;void main(){vDirection=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:'varying vec3 vDirection;uniform float uNight;void main(){vec3 d=normalize(vDirection);float h=clamp(d.y,0.,1.);vec3 horizon=mix(vec3(.76,.79,.70),vec3(.065,.09,.14),uNight);vec3 zenith=mix(vec3(.28,.49,.65),vec3(.012,.024,.055),uNight);vec3 c=mix(horizon,zenith,pow(h,.45));float sun=pow(max(0.,dot(d,normalize(vec3(-.5,.3,-.6)))),1000.);float glow=pow(max(0.,dot(d,normalize(vec3(-.5,.3,-.6)))),12.);c+=mix(vec3(1.,.75,.43),vec3(.2,.25,.3),uNight)*(sun*1.7+glow*.07);gl_FragColor=vec4(c,1.);\n#include <tonemapping_fragment>\n#include <colorspace_fragment>\n}'});sky=new T.Mesh(new T.SphereGeometry(1500,40,20),skyMaterial);sky.frustumCulled=false;sky.visible=false;scene.add(sky)}
function applyEnvironment(){if(!scene)return;const driving=ui.mode==='drive';sky.visible=driving;skyMaterial.uniforms.uNight.value=ui.night?1:0;scene.background=driving?new T.Color(ui.night?'#182837':'#a4bfc7'):null;scene.fog=driving?new T.Fog(ui.night?'#1d303b':ui.wet?'#a2b4b3':'#a6bdb8',ui.wet?130:230,ui.wet?650:1050):new T.Fog('#273534',20,80);scene.environmentIntensity=driving?(ui.night?.16:.85):1;hemi.intensity=driving?(ui.night?.22:2.0):1.0;sun.intensity=driving?(ui.night?.12:ui.wet?1.7:3.3):4.0;fill.intensity=driving?(ui.night?.15:.4):1.4;sun.color.set(driving?(ui.night?'#a8c6e3':'#fff0d4'):ui.warm?'#ffe1c1':'#d2e4ff');if(driving){Object.assign(sun.shadow.camera,{left:-20,right:20,top:20,bottom:-20,near:1,far:140});}else{sun.position.set(-4,8,-6);sun.target.position.set(0,.5,0);Object.assign(sun.shadow.camera,{left:-6,right:6,top:6,bottom:-6,near:.5,far:40});}sun.shadow.camera.updateProjectionMatrix();$('#viewport').classList.toggle('night',driving&&ui.night);if(car){for(const m of car.materials){if(/Windows|Clear_Glass/.test(m.name))m.opacity=driving?.055:/Windows_alpha|Clear_Glass/.test(m.name)?.17:.26}car.setLights(driving?ui.headlights:true)}if(headlampGroup)headlampGroup.visible=driving&&ui.headlights;if(ambientCockpit)ambientCockpit.intensity=driving?(ui.night?.48:.12):0;}
function makeGarage(){garage=new T.Group();scene.add(garage);const floor=new T.Mesh(new T.PlaneGeometry(100,100),new T.MeshStandardMaterial({color:'#3b4944',roughness:.4,metalness:.35}));floor.rotation.x=-Math.PI/2;floor.position.y=-.09;floor.receiveShadow=true;garage.add(floor);const base=new T.Mesh(new T.CylinderGeometry(3.05,3.1,.06,100),new T.MeshPhysicalMaterial({color:'#343e39',metalness:.35,roughness:.35,clearcoat:.2}));base.position.y=-.05;base.receiveShadow=true;garage.add(base);for(const r of [3.13,3.32,5]){const ring=new T.Mesh(new T.RingGeometry(r,r+.008,140),new T.MeshBasicMaterial({color:r===3.13?'#ae9570':'#778d79',side:T.DoubleSide,transparent:true,opacity:r===5?.16:.35}));ring.rotation.x=-Math.PI/2;ring.position.y=-.055;garage.add(ring)}const grid=new T.GridHelper(50,40,'#7c8d77','#7c8d77');grid.position.y=-.085;grid.material.transparent=true;grid.material.opacity=.08;garage.add(grid);for(const x of [-6,6]){const post=new T.Mesh(new T.BoxGeometry(.04,5,.04),new T.MeshStandardMaterial({color:'#61706a',metalness:.7,roughness:.4}));post.position.set(x,2.4,1);garage.add(post);const panel=new T.Mesh(new T.PlaneGeometry(.12,3.7),new T.MeshBasicMaterial({color:'#e8edd1'}));panel.position.set(x,2.4,.96);panel.rotation.y=x>0?-.3:.3;garage.add(panel)}}
function makeHeadlights(){headlampGroup=new T.Group();car.group.add(headlampGroup);for(const x of [-.68,.68]){const spot=new T.SpotLight('#f9ebce',65,65,.27,.65,1.3);spot.position.set(x,.49,-1.91);const target=new T.Object3D();target.position.set(x*.65,.12,-27);spot.target=target;headlampGroup.add(spot,target)}headlampGroup.visible=false;ambientCockpit=new T.PointLight('#d3b18e',.1,1.9,1);ambientCockpit.position.set(-.25,.93,-.35);car.group.add(ambientCockpit)}
function bindCanvas(){let down={x:0,y:0},drag=false;renderer.domElement.addEventListener('pointerdown',e=>{down={x:e.clientX,y:e.clientY};drag=false;if(ui.mode==='drive'){renderer.domElement.setPointerCapture(e.pointerId);renderer.domElement.dataset.look='1'}});renderer.domElement.addEventListener('pointermove',e=>{if(ui.mode!=='drive'||renderer.domElement.dataset.look!=='1')return;const dx=e.clientX-down.x,dy=e.clientY-down.y;if(Math.hypot(dx,dy)>2)drag=true;ui.lookYaw=clamp(ui.lookYaw-dx*.003,-1.35,1.35);ui.lookPitch=clamp(ui.lookPitch-dy*.003,-.75,.50);down={x:e.clientX,y:e.clientY}});renderer.domElement.addEventListener('pointerup',e=>{renderer.domElement.dataset.look='0';if(ui.mode==='drive'&&drag)return;if(ui.mode==='garage'&&Math.hypot(e.clientX-down.x,e.clientY-down.y)>5)return;const r=renderer.domElement.getBoundingClientRect();mouse.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(mouse,camera);const hit=ray.intersectObject(car.group,true).find(h=>h.object.isMesh&&car.getPartFromObject(h.object)&&!(ui.mode==='garage'&&(Array.isArray(h.object.material)?h.object.material:[h.object.material]).every(m=>m.transparent&&m.opacity<.4)));if(!hit)return;const part=car.getPartFromObject(hit.object);if(ui.mode==='garage'){if(part){selectPart(part.id);if(innerWidth<=600&&$('.inspector').getBoundingClientRect().top>innerHeight-100)toast(part.name+' — действия под моделью.')}}else{const local=car.group.worldToLocal(hit.point.clone());if(hit.distance<1.0){reachTo(local);toast(part?'Касание: '+part.name:'Касание салона');if(part?.id==='steering')audio.horn();}else toast('Осмотр детали: '+(part?.name||'поверхность'));}});renderer.domElement.addEventListener('pointercancel',()=>renderer.domElement.dataset.look='0');}
function driveFrame(dt,s,time){car.group.position.set(s.position.x,.004,s.position.z);car.group.rotation.set(s.pitch,s.yaw,s.roll,'YXZ');car.group.updateMatrixWorld(true);world.update(s.position,time);sky.position.set(s.position.x,0,s.position.z);sun.position.set(s.position.x-38,55,s.position.z-25);sun.target.position.set(s.position.x,0,s.position.z);if(ui.chase){const target=car.group.localToWorld(new T.Vector3(0,2.1,5.5));camera.position.lerp(target,1-Math.exp(-dt*5));camera.lookAt(car.group.localToWorld(new T.Vector3(0,.8,-2.5)));}else{const bob=ui.wet?.25:1,eye=new T.Vector3(...car.metadata.driverEye).add(new T.Vector3(s.headOffset.x,s.headOffset.y*bob,s.headOffset.z));camera.position.copy(car.group.localToWorld(eye));camera.quaternion.copy(car.group.quaternion).multiply(new T.Quaternion().setFromEuler(new T.Euler(ui.lookPitch,ui.lookYaw,0,'YXZ')));}ui.reachTime=Math.max(0,ui.reachTime-dt);const reach=ui.reachTime>0?Math.sin((1.25-ui.reachTime)/1.25*Math.PI):0;hands.update(dt,{steer:s.steeringWheel,reach,target:reachTarget});if(ui.wipers){const w=car.parts.find(p=>p.id==='wipers');if(w)w.group.rotateY(Math.sin(time*4)*.55);}let best=Infinity,bestIndex=0;for(let i=0;i<touchPoints.length;i++){const p=car.group.localToWorld(touchPoints[i].pos.clone()).project(camera),d=Math.hypot(p.x,p.y);if(p.z<1&&d<best){best=d;bestIndex=i}}ui.interaction=bestIndex;$('#interactionHint').textContent=!s.engineOn?'Нажмите «Завести и ехать»':best<.75?touchPoints[bestIndex].name+' · E':'Потяните мышью, чтобы осмотреться';}
async function init(){try{renderer=new T.WebGLRenderer({antialias:true,alpha:true,powerPreference:'high-performance',preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,innerWidth<700?1.35:1.6));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.setClearColor(0x000000,0);$('#canvas').appendChild(renderer.domElement);scene=new T.Scene();camera=new T.PerspectiveCamera(38,1,.04,500);orbit=new OrbitControls(camera,renderer.domElement);orbit.enableDamping=true;orbit.dampingFactor=.07;orbit.maxPolarAngle=Math.PI*.49;orbit.minPolarAngle=.10;orbit.enablePan=true;new ResizeObserver(resize).observe($('#canvas'));resize();fitGarage();hemi=new T.HemisphereLight('#dfe9ec','#484335',1);scene.add(hemi);sun=new T.DirectionalLight('#ffe1c1',4);sun.position.set(-4,8,-6);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.normalBias=.016;sun.shadow.bias=-.00015;scene.add(sun,sun.target);fill=new T.DirectionalLight('#bfdad7',1.4);fill.position.set(4,3,4);scene.add(fill);makeGarage();makeSky();world=new DrivingWorld(scene);world.setEnabled(false);world.setWeather('clear');
const envPromise=new RGBELoader().loadAsync('assets/studio.hdr').then(texture=>{texture.mapping=T.EquirectangularReflectionMapping;const pmrem=new T.PMREMGenerator(renderer),env=pmrem.fromEquirectangular(texture);envTexture=env.texture;scene.environment=envTexture;texture.dispose();pmrem.dispose()}).catch(()=>{scene.environment=null;toast('Освещение студии загружено в упрощённом режиме')});
car=await loadCar((ratio,text)=>{$('#loadBar').style.width=ratio*95+'%';$('#loadText').textContent=text});scene.add(car.group);car.setColor(ui.color);makeHeadlights();handMount=new T.Group();handMount.position.fromArray(car.metadata.steeringCenter);handMount.rotation.x=-Math.asin(.215315);car.group.add(handMount);hands=new DriverHands(handMount);hands.setEnabled(false);await Promise.all([hands.ready,envPromise]);if(hands.loadError)toast('Модель рук не загрузилась; вождение доступно.');$('#modelCredits').innerHTML='<p><strong>McLaren P1</strong>, DAVID.3D.ART: <a href="https://sketchfab.com/3d-models/ac-mclaren-p1-free-747cedadc302451db61deafc85941395" target="_blank" rel="noreferrer">исходная модель</a>, <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0 — некоммерческое использование</a>. 203 306 треугольников и 27 текстур. Сохранены атрибуция и лицензия. Дополнительные моторный блок и передний отсек обозначены как условные схемы.</p><p>Руки: WebXR Input Profiles / Amazon, MIT. Окружение студии: <a href="https://polyhaven.com/a/studio_small_09" target="_blank" rel="noreferrer">Poly Haven, Studio Small 09</a>, CC0. Three.js r170, MIT.</p>';renderParts();selectPart('hood');bindCanvas();ready=true;$('#loadBar').style.width='100%';$('#loader').hidden=true;applyEnvironment();let previous=performance.now();function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-previous)/1000,.05),time=now/1000;previous=now;if(ui.mode==='drive'){const currentInput=input();simulation.setInput(currentInput);const s=simulation.update(dt);car.update(dt,{...s,steeringWheel:-clamp(s.steeringWheel*.23,-.85,.85)});driveFrame(dt,s,time);audio.update(dt,{...s,wet:ui.wet});if(time-lastUI>.06){syncDriveUI(s);minimap(s);lastUI=time}}else{car.update(dt);orbit.update();}renderer.render(scene,camera)}requestAnimationFrame(frame);}catch(error){console.error(error);$('#loader').innerHTML='<b>Не удалось открыть автомобиль</b><span>Проверьте WebGL, соединение и запуск через HTTP-сервер.</span><button id="retry" class="primary-button" style="width:auto;margin-top:10px">Повторить ↻</button>';$('#retry').onclick=()=>location.reload()}}
init();
